# ---------------------------------------------------------------------------
# Bali proposals. Fields: type, subtype, format, location, per_article,
# facets, series_key, kind, confidence, decisions, reasoning, alternates,
# container (True when the category is a parent whose children carry the prior)
# ---------------------------------------------------------------------------
_B = "bali"


def _p(type_=None, subtype=None, format_=None, location=_B, per_article=(), facets=None, series_key=None, kind="editorial",
       confidence="high", decisions=(), reasoning="", alternates=(), container=False, auto=True):
    return {"type": type_, "subtype": subtype, "format": format_, "location": location, "per_article": list(per_article),
            "facets": facets or {}, "series_key": series_key, "kind": kind, "confidence": confidence, "decisions": list(decisions),
            "reasoning": reasoning, "alternates": list(alternates), "container": container, "auto": auto}


